import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BZAK_utg.js";const c=JSON.parse('{"title":"构建Java云原生镜像：基于Quarkus的镜像","description":"","frontmatter":{"title":"构建Java云原生镜像：基于Quarkus的镜像","date":"2023-12-05","categories":["编程语言","Java"],"tags":["Java","Quarkus","K8S","Docker"],"prevTitle":"构建Java云原生镜像：基于SpringBoot的分层镜像","prevLink":"./构建Java云原生镜像：基于SpringBoot的分层镜像.html","nextTitle":"数据结构知识大纲","nextLink":"../数据结构/数据结构知识大纲.html"},"headers":[],"relativePath":"posts/编程语言/构建Java云原生镜像：基于Quarkus的镜像.md","filePath":"posts/编程语言/构建Java云原生镜像：基于Quarkus的镜像.md"}'),l={name:"posts/编程语言/构建Java云原生镜像：基于Quarkus的镜像.md"};function p(h,a,n,r,k,o){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="构建java云原生镜像-基于quarkus的镜像" tabindex="-1">构建Java云原生镜像：基于Quarkus的镜像 <a class="header-anchor" href="#构建java云原生镜像-基于quarkus的镜像" aria-label="Permalink to &quot;构建Java云原生镜像：基于Quarkus的镜像&quot;">​</a></h1><h2 id="一、准备一个quarkus项目" tabindex="-1">一、准备一个Quarkus项目 <a class="header-anchor" href="#一、准备一个quarkus项目" aria-label="Permalink to &quot;一、准备一个Quarkus项目&quot;">​</a></h2><p>可使用<a href="https://quarkus.io/guides/cli-tooling" target="_blank" rel="noreferrer">Quarkus CLI</a>快速生成一个Quarkus项目，如下所示：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quarkus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span></code></pre></div><p>该命令将生成一个名为<code>code-with-quarkus</code>的项目，如果不想使用<code>quarkus-cli</code>，也可基于<a href="https://code.quarkus.io" target="_blank" rel="noreferrer">Quarkus脚手架</a>或<a href="https://quarkus.io/guides/ide-tooling" target="_blank" rel="noreferrer">IDE插件</a>创建项目。</p><p>进入项目根目录，编译运行：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quarkus:dev</span></span></code></pre></div><p>或生成jar包后运行：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dquarkus.package.type=uber-jar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jar</span></span></code></pre></div><p>验证应用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/hello</span></span></code></pre></div><h2 id="二、构建可执行文件" tabindex="-1">二、构建可执行文件 <a class="header-anchor" href="#二、构建可执行文件" aria-label="Permalink to &quot;二、构建可执行文件&quot;">​</a></h2><p>执行maven打包时，<code>quarkus-maven-plugin</code>插件可根据<code>quarkus.package.type</code>配置的值决定生成文件的类型，配置为<code>uber-jar</code>生成则可执行jar包（如<a href="#一准备一个quarkus项目">前文</a>所示），配置为<code>native</code>则生成原生可执行文件，如下所示：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dquarkus.package.type=native</span></span></code></pre></div><p>运行可执行文件：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/*-runner</span></span></code></pre></div><p>验证应用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/hello</span></span></code></pre></div><p>上述生成可执行文件的命令需要GraalVM环境，如果不想配置GraalVM，也可以使用Docker完成构建：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dquarkus.package.type=native</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dquarkus.native.container-build=true</span></span></code></pre></div><blockquote><p>ARM架构的MacBook电脑可能会执行失败，可暂时使用x86机器构建。</p></blockquote><h2 id="三、构建镜像" tabindex="-1">三、构建镜像 <a class="header-anchor" href="#三、构建镜像" aria-label="Permalink to &quot;三、构建镜像&quot;">​</a></h2><p>使用<code>quarkus-maven-plugin</code>插件的<code>image-build</code>执行目标构建Docker镜像：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quarkus:image-build</span></span></code></pre></div><p>该命令会生成一个Docker镜像，如：<code>luanrz/code-with-quarkus:1.0.0-SNAPSHOT</code>。</p><p>运行容器：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luanrz/code-with-quarkus:1.0.0-SNAPSHOT</span></span></code></pre></div><p>验证应用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/hello</span></span></code></pre></div><blockquote><p>参考文档</p></blockquote><ol><li><a href="https://quarkus.io" target="_blank" rel="noreferrer">Quarkus官方网站</a></li><li><a href="https://www.graalvm.org" target="_blank" rel="noreferrer">GraalVM官方网站</a></li></ol>`,31)])])}const u=s(l,[["render",p]]);export{c as __pageData,u as default};
